package com.panish.ridebooking.driver.service;
import com.panish.ridebooking.driver.domain.*;import com.panish.ridebooking.driver.repository.*;import com.panish.ridebooking.events.*;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.UUID;
@Service public class DriverAssignmentService {private final DriverRepository drivers;private final ProcessedEventRepository processed;private final KafkaTemplate<String,Object> kafka;public DriverAssignmentService(DriverRepository d,ProcessedEventRepository p,KafkaTemplate<String,Object> k){drivers=d;processed=p;kafka=k;}@Transactional public void assign(RideCreatedEvent event){if(event.eventId()==null||processed.existsById(event.eventId()))return;Driver driver=drivers.findFirstByStatusOrderByIdAsc("AVAILABLE").orElse(null);if(driver==null){kafka.send("driver-assignment-failed-topic",String.valueOf(event.rideId()),new DriverAssignmentFailedEvent(UUID.randomUUID().toString(),event.rideId(),"No drivers are currently available"));}else{driver.setStatus("BUSY");drivers.save(driver);kafka.send("driver-assigned-topic",String.valueOf(event.rideId()),new DriverAssignedEvent(UUID.randomUUID().toString(),event.rideId(),driver.getId(),driver.getName()));}processed.save(new ProcessedEvent(event.eventId()));}}